html,body{overflow-x:hidden;}
.cp-sec{--padding-top:88px;--padding-bottom:88px;--padding-left:48px;--padding-right:48px;font-family:'Noto Sans JP',sans-serif;}
.cp-sec,.cp-sec p,.cp-sec li,.cp-sec a,.cp-sec .elementor-heading-title{font-family:'Noto Sans JP',sans-serif;}
.cp-sec>.e-con-inner,.cp-sec>.elementor-element{max-width:1200px;margin-left:auto;margin-right:auto;width:100%;}
@media(max-width:1024px){.cp-sec{--padding-top:64px;--padding-bottom:64px;--padding-left:32px;--padding-right:32px;}}
@media(max-width:767px){.cp-sec{--padding-top:52px;--padding-bottom:52px;--padding-left:20px;--padding-right:20px;}}
.cp-sec p:last-child{margin-bottom:0;}
.cp-eyebrow{display:inline-block;margin:0;color:#F5F3EE;border:1.5px solid #F5F3EE;padding:5px 12px;font-size:13px;font-weight:700;letter-spacing:.12em;}
.cp-hero .cp-hero-logo img{width:100%;max-width:520px;height:auto;}
.cp-hero-h1 .elementor-heading-title{font-size:clamp(30px,4.4vw,56px)!important;line-height:1.25!important;letter-spacing:.03em;color:#F5F3EE;}
.cp-hero-lead{color:#F5F3EE;font-size:16px;line-height:1.9;margin:0;}
.cp-btns{display:flex;flex-wrap:wrap;gap:14px;}
.cp-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:14px 26px;font-weight:900;font-size:16px;letter-spacing:.06em;text-decoration:none!important;border:2px solid #111;transition:transform .15s,box-shadow .15s;}
.cp-btn-main{background:#F04B2A;color:#111!important;box-shadow:4px 4px 0 #F5F3EE;}
.cp-btn-main:hover{transform:translate(-2px,-2px);box-shadow:6px 6px 0 #F5F3EE;}
.cp-btn-sub{background:transparent;color:#F5F3EE!important;border-color:#F5F3EE;}
.cp-btn-sub:hover{background:#F5F3EE;color:#111!important;}
.cp-light .cp-btn-main{box-shadow:4px 4px 0 #111;}
.cp-light .cp-btn-sub{color:#111!important;border-color:#111;}
@media(max-width:767px){.cp-btn{width:100%;}}
.cp-board{border:4px double #F5F3EE;padding:26px 26px 22px;color:#F5F3EE;background:#111;}
.cp-board-t{margin:0 0 10px;text-align:center;font-weight:900;font-size:15px;letter-spacing:.2em;border-bottom:1.5px solid #F04B2A;padding-bottom:10px;color:#F04B2A;}
.cp-board ul{list-style:none;margin:0;padding:0;}
.cp-board li{display:flex;align-items:baseline;gap:8px;padding:11px 0;font-size:15px;margin:0;}
.cp-board li span{flex:none;}
.cp-board li i{flex:1;border-bottom:2px dotted rgba(245,243,238,.45);min-width:12px;transform:translateY(-4px);}
.cp-board li b{flex:none;font-weight:900;text-align:right;}
.cp-board-n{margin:14px 0 0;font-size:13px;opacity:.8;text-align:center;}
@media(max-width:400px){.cp-board{padding:20px 16px;}.cp-board li{font-size:14px;flex-wrap:wrap;}.cp-board li i{display:none;}.cp-board li b{width:100%;text-align:left;}}
.cp-label{display:inline-block;margin:0 0 4px;padding:4px 10px;border:1.5px solid currentColor;font-size:12px;font-weight:700;letter-spacing:.16em;}
.cp-h2 .elementor-heading-title{font-size:clamp(26px,3.2vw,40px)!important;font-weight:900!important;line-height:1.35!important;letter-spacing:.04em;}
.cp-lead{font-size:16px;line-height:1.9;margin:0;}
.cp-grid{display:grid;gap:22px;grid-template-columns:repeat(3,minmax(0,1fr));}
.cp-grid.g4{grid-template-columns:repeat(4,minmax(0,1fr));}
@media(max-width:1024px){.cp-grid,.cp-grid.g4{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:767px){.cp-grid,.cp-grid.g4{grid-template-columns:1fr;}}
.cp-card{display:flex;flex-direction:column;background:#F5F3EE;color:#111!important;border:2px solid #111;box-shadow:5px 5px 0 #111;padding:22px;text-decoration:none!important;transition:transform .15s,box-shadow .15s;}
a.cp-card:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 #111;}
.cp-dark .cp-card{box-shadow:5px 5px 0 #F04B2A;}
.cp-dark a.cp-card:hover{box-shadow:7px 7px 0 #F04B2A;}
.cp-card h3{font-size:19px;font-weight:900;margin:0 0 8px;color:#111;line-height:1.45;}
.cp-card p{font-size:14.5px;line-height:1.85;margin:0 0 14px;color:#111;}
.cp-card .cp-more{margin-top:auto;font-weight:700;font-size:14px;border-top:1.5px dashed #111;padding-top:10px;}
.cp-card .cp-img{background:#111;margin:-22px -22px 16px;border-bottom:2px solid #111;}
.cp-card .cp-img img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:contain;}
.cp-no{display:block;font-size:12px;font-weight:700;letter-spacing:.16em;color:#1E3354;margin-bottom:6px;}
.cp-card.hot{background:#F04B2A;}
.cp-card.hot .cp-no{color:#111;}
.cp-price{font-size:13.5px;line-height:1.7;border:1.5px solid #111;padding:8px 10px;margin:0 0 14px;}
.cp-method{border-top:6px solid var(--m);}
.cp-method .cp-no{color:var(--m);}
.cp-curve{display:grid;grid-template-columns:1.1fr 1fr;gap:32px;align-items:center;background:#111;color:#F5F3EE;border:2px solid #111;padding:32px;margin-top:8px;}
@media(max-width:1024px){.cp-curve{grid-template-columns:1fr;padding:24px;}}
@media(max-width:767px){.cp-curve{padding:20px 16px;}}
.cp-curve h3{color:#F5F3EE;font-size:clamp(22px,2.6vw,30px);font-weight:900;margin:6px 0 12px;line-height:1.4;}
.cp-curve p{color:#F5F3EE;font-size:15px;line-height:1.9;margin:0 0 18px;}
.cp-curve .cp-label{color:#F04B2A;}
.cp-curve svg{width:100%;height:auto;display:block;background:#F5F3EE;border:2px solid #F5F3EE;}
.cp-curve .cp-note{font-size:12px;opacity:.75;margin:8px 0 0;}
.cp-faq details{border:2px solid #111;background:#F5F3EE;margin:0 0 12px;box-shadow:4px 4px 0 #111;}
.cp-faq summary{cursor:pointer;list-style:none;padding:16px 48px 16px 18px;font-weight:900;font-size:16px;line-height:1.6;position:relative;color:#111;}
.cp-faq summary::-webkit-details-marker{display:none;}
.cp-faq summary::before{content:"Q.";color:#F04B2A;margin-right:8px;}
.cp-faq summary::after{content:"+";position:absolute;right:18px;top:12px;font-size:22px;font-weight:400;}
.cp-faq details[open] summary::after{content:"\2212";}
.cp-faq .cp-a{padding:0 18px 18px;font-size:15px;line-height:1.9;color:#111;border-top:1.5px dashed #111;padding-top:14px;margin:0 18px;padding-left:0;padding-right:0;}
.cp-cta{border:4px double #F5F3EE;padding:36px 28px;text-align:center;color:#F5F3EE;}
.cp-cta h3{color:#F5F3EE;font-size:clamp(22px,2.8vw,32px);font-weight:900;margin:0 0 10px;line-height:1.45;}
.cp-cta p{margin:0 0 22px;font-size:15px;line-height:1.8;}
.cp-cta .cp-btns{justify-content:center;}
.cp-cta small{display:block;margin-top:16px;font-size:13px;}
.cp-cta small a{color:#F5F3EE;text-decoration:underline;}
</style>				</div>
